bool IsMenuLocalizationEnabled() {
#ifdef DISABLE_MENU_LOCALIZATION
    return false;
#else
    return CVarGetInteger("gEnhancements.Localization.TranslateMenu", 1) != 0;
#endif
}

const ImWchar* GetChineseFontGlyphRanges(ImFontAtlas* fonts) {
    static ImVector<ImWchar> sMergedRanges;
    if (sMergedRanges.empty()) {
        ImFontGlyphRangesBuilder builder;
        if (fonts != nullptr) {
            builder.AddRanges(fonts->GetGlyphRangesChineseSimplifiedCommon());
        }
        auto addMapGlyphs = [&builder](const std::unordered_map<std::string, std::string>& m) {
            for (const auto& pair : m) {
                builder.AddText(pair.second.c_str());
            }
        };
        addMapGlyphs(sHeaderMap);
        addMapGlyphs(sSidebarMap);
        addMapGlyphs(sWidgetNameMap);
        addMapGlyphs(sTooltipMap);
        addMapGlyphs(sComboOptionMap);
        builder.AddText("搜索设置项...搜索结果清除搜索清空输入关键词以搜索配置项...未找到匹配结果退出游戏确定要退出时光之笛 (SoH) 吗？退出取消重置游戏关闭设置菜单 (-)当前设置因以下原因被禁用：过滤 (包含,-排除)已包含已排除全部收起全部展开排除当前可见项包含当前可见项无标签部分启用全部启用禁用当前可见项启用当前可见项已禁用已启用");
        builder.BuildRanges(&sMergedRanges);
    }
    return sMergedRanges.Data;
}

std::string TranslateHeader(const std::string& header) {
    if (!IsMenuLocalizationEnabled()) return header;
    auto it = sHeaderMap.find(header);
    return (it != sHeaderMap.end()) ? it->second : header;
}

std::string TranslateSidebar(const std::string& sidebar) {
    if (!IsMenuLocalizationEnabled()) return sidebar;
    auto it = sSidebarMap.find(sidebar);
    return (it != sSidebarMap.end()) ? it->second : sidebar;
}

std::string TranslateWidgetName(const std::string& name) {
    if (!IsMenuLocalizationEnabled() || name.empty()) return name;
    auto itDirect = sWidgetNameMap.find(name);
    if (itDirect != sWidgetNameMap.end()) {
        return itDirect->second;
    }
    size_t hashPos = name.find("##");
    if (hashPos != std::string::npos) {
        std::string baseName = name.substr(0, hashPos);
        std::string suffix = name.substr(hashPos);
        auto itBase = sWidgetNameMap.find(baseName);
        if (itBase != sWidgetNameMap.end()) {
            return itBase->second + suffix;
        }
    }
    return name;
}

std::string TranslateTooltip(const std::string& tooltip) {
    if (!IsMenuLocalizationEnabled() || tooltip.empty()) return tooltip;
    auto it = sTooltipMap.find(tooltip);
    if (it != sTooltipMap.end()) {
        return it->second;
    }
    const std::string prefix = "This setting is disabled because: \n";
    if (tooltip.rfind(prefix, 0) == 0) {
        std::string result = "当前设置因以下原因被禁用：\n";
        size_t pos = prefix.size();
        while (pos < tooltip.size()) {
            size_t nextNl = tooltip.find('\n', pos);
            std::string line = (nextNl == std::string::npos) ? tooltip.substr(pos) : tooltip.substr(pos, nextNl - pos);
            if (line.rfind("- ", 0) == 0) {
                std::string reason = line.substr(2);
                auto itReason = sTooltipMap.find(reason);
                if (itReason != sTooltipMap.end()) {
                    result += "- " + itReason->second;
                } else {
                    result += line;
                }
            } else {
                result += line;
            }
            if (nextNl == std::string::npos) break;
            result += "\n";
            pos = nextNl + 1;
        }
        return result;
    }
    return tooltip;
}

std::string TranslateOption(const std::string& option) {
    if (!IsMenuLocalizationEnabled() || option.empty()) return option;
    auto itCombo = sComboOptionMap.find(option);
    if (itCombo != sComboOptionMap.end()) {
        return itCombo->second;
    }
    return TranslateWidgetName(option);
}

const char* TranslateComboOption(const char* option) {
    if (!option || !IsMenuLocalizationEnabled()) return option;
    auto it = sComboOptionMap.find(option);
    return (it != sComboOptionMap.end()) ? it->second.c_str() : option;
}

void ApplySohMenuLocalization(std::unordered_map<std::string, MainMenuEntry>& menuEntries) {
    if (!IsMenuLocalizationEnabled()) {
        return;
    }

    for (auto& [menuKey, menuEntry] : menuEntries) {
        for (auto& [sidebarKey, sidebar] : menuEntry.sidebars) {
            for (auto& col : sidebar.columnWidgets) {
                for (auto& widget : col) {
                    widget.name = TranslateWidgetName(widget.name);

                    if (widget.options) {
                        if (!widget.options->tooltip.empty()) {
                            widget.options->tooltip = TranslateTooltip(widget.options->tooltip);
                        }

                        if (!widget.options->disabledTooltip.empty()) {
                            widget.options->disabledTooltip = TranslateTooltip(widget.options->disabledTooltip);
                        }
                    }

                    if (widget.type == WIDGET_COMBOBOX || widget.type == WIDGET_CVAR_COMBOBOX ||
                        widget.type == WIDGET_AUDIO_BACKEND || widget.type == WIDGET_VIDEO_BACKEND) {
                        auto comboOpt = std::static_pointer_cast<UIWidgets::ComboboxOptions>(widget.options);
                        if (comboOpt) {
                            for (auto& pair : comboOpt->comboMap) {
                                if (pair.second) {
                                    auto itCombo = sComboOptionMap.find(pair.second);
                                    if (itCombo != sComboOptionMap.end()) {
                                        pair.second = itCombo->second.c_str();
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

